@test_timeout(4 * 60)
def test_mendel_errors_8(self):
    mt = hl.import_vcf(resource('mendel.vcf'))
    ped = hl.Pedigree.read(resource('mendel.fam'))
    men, fam, ind, var = hl.mendel_errors(mt['GT'], ped)
    to_keep = hl.set([(hl.Locus('1', 1), ['C', 'CT']), (hl.Locus('1', 2), ['C', 'T']), (hl.Locus('X', 1), ['C', 'T']), (hl.Locus('X', 3), ['C', 'T']), (hl.Locus('Y', 1), ['C', 'T']), (hl.Locus('Y', 3), ['C', 'T'])])
    var = var.filter(to_keep.contains((var.locus, var.alleles)))
    var = var.order_by('locus')
    var = var.select('locus', 'alleles', 'errors')
    actual = var.collect()
    expected = [hl.utils.Struct(locus=hl.Locus('1', 1), alleles=['C', 'CT'], errors=2), hl.utils.Struct(locus=hl.Locus('1', 2), alleles=['C', 'T'], errors=1), hl.utils.Struct(locus=hl.Locus('X', 1), alleles=['C', 'T'], errors=2), hl.utils.Struct(locus=hl.Locus('X', 3), alleles=['C', 'T'], errors=1), hl.utils.Struct(locus=hl.Locus('Y', 1), alleles=['C', 'T'], errors=1), hl.utils.Struct(locus=hl.Locus('Y', 3), alleles=['C', 'T'], errors=1)]
    assert actual == expected
